window.V2_LEXICON={"fr_aborder_verb":{"id":"fr_aborder_verb","lex":true,"fr":"aborder","en":"to approach; to tackle","ipa":"/a.bɔʁ.de/","say":"ah-bor-DAY","cefr":"B1","ex":["Nous allons aborder un nouveau sujet.","We're going to tackle a new topic."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_approcher_verb","fr":"approcher","hw":"approcher","en":"to approach","note":"Approcher is to come near. Aborder is to go up to someone, to take up a topic, or to land.","at":null,"lex":true}]},"fr_abri_noun":{"id":"fr_abri_noun","lex":true,"fr":"abri","en":"shelter","ipa":"/a.bʁi/","say":"ah-BREE","cefr":"B1","ex":["Nous cherchons un abri contre la pluie.","We're looking for shelter from the rain."],"noMnemonic":true,"g":"m","art":"l'","ind":"un","compares":[{"to":"fr_gite_noun","fr":"gîte","hw":"le gîte","en":"shelter; lodging; gîte","note":"Gîte is a lodging, or a holiday cottage. Abri is a shelter.","at":["camping","souche"]}]},"fr_admettre_verb":{"id":"fr_admettre_verb","lex":true,"fr":"admettre","en":"to admit","ipa":"/ad.mɛtʁ/","say":"ahd-MEHTR","cefr":"A2","ex":["J'admets que j'ai eu tort.","I admit that I was wrong."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_avouer_verb","fr":"avouer","hw":"avouer","en":"to admit","note":"Avouer is to confess. Admettre is to grant that something is so, or to allow someone in.","at":null,"lex":true}]},"fr_affaiblir_verb":{"id":"fr_affaiblir_verb","lex":true,"fr":"affaiblir","en":"to weaken; to weaken, to become weaker","ipa":"/a.fɛ.bliʁ/","say":"ah-fay-BLEER","cefr":"B2","ex":["La maladie l'a affaibli.","The illness weakened him."],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_decliner_verb","fr":"décliner","hw":"décliner","en":"to weaken; to enumerate","note":"Décliner is to decline, to go down after a high point, or to turn aside. Affaiblir is to make someone or something weaker.","at":null,"lex":true}]},"fr_aggraver_verb":{"id":"fr_aggraver_verb","lex":true,"fr":"aggraver","en":"to worsen","ipa":"/a.ɡʁa.ve/","say":"ah-grah-VAY","cefr":"B2","ex":["La situation s'aggrave.","The situation is getting worse."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_pervertir_verb","fr":"pervertir","hw":"pervertir","en":"to worsen; to corrupt","note":"Pervertir is to corrupt someone, to turn them toward harm. Aggraver is to make a bad situation worse.","at":["contes","grande_salle"]}]},"fr_aimer_verb":{"id":"fr_aimer_verb","lex":true,"fr":"aimer","en":"to love; to like","ipa":"/ɛ.me/","say":"ay-MAY","cefr":"A1","ex":["J'aime beaucoup la musique.","I like music a lot."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_adorer_verb","fr":"adorer","hw":"adorer","en":"to love, to adore; to worship","note":"Adorer is stronger than aimer, or it means to worship. Aimer is to like or to love.","at":["eglise","misericorde"]}]},"fr_aliment_noun":{"id":"fr_aliment_noun","lex":true,"fr":"aliment","en":"food","ipa":"/a.li.mɑ̃/","say":"ah-lee-MAHN","cefr":"B1","ex":["Le pain est un aliment de base.","Bread is a staple food."],"noMnemonic":true,"g":"m","art":"l'","ind":"un","compares":[{"to":"fr_alimentation_noun","fr":"alimentation","hw":"l'alimentation","en":"food; diet","note":"Alimentation is diet or food supply. Aliment is one food.","at":["maison","salle"]},{"to":"fr_nourriture_noun","fr":"nourriture","hw":"la nourriture","en":"food","note":"Nourriture is food as a mass. Aliment is a single food.","at":null,"lex":true}]},"fr_alimenter_verb":{"id":"fr_alimenter_verb","lex":true,"fr":"alimenter","en":"to feed; to supply (power, water)","ipa":"/a.li.mɑ̃.te/","say":"ah-lee-mahn-TAY","cefr":"B2","ex":["Ce barrage alimente toute la ville en électricité.","This dam supplies the whole town with electricity."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_nourrir_verb","fr":"nourrir","hw":"nourrir","en":"to feed","note":"Nourrir is to feed. Alimenter is to feed into a system, or to supply it.","at":["ferme","ferme"]}]},"fr_amener_verb":{"id":"fr_amener_verb","lex":true,"fr":"amener","en":"to bring","ipa":"/am.ne/","say":"ah-muh-NAY","cefr":"A2","ex":["Tu peux amener ton ami à la fête.","You can bring your friend to the party."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_apporter_verb","fr":"apporter","hw":"apporter","en":"to bring","note":"Apporter is usual for a thing. Amener is usual for a person or an animal.","at":null,"lex":true,"examples":[{"who":"apporter","fr":"J'apporte le dessert.","en":"I'm bringing dessert."},{"who":"amener","fr":"J'amène mon frère.","en":"I'm bringing my brother."}]},{"to":"fr_emmener_verb","fr":"emmener","hw":"emmener","en":"to take (someone) along","note":"Emmener is to take a person away from here. Amener is to bring a person here.","at":null,"lex":true}]},"fr_apparaitre_verb":{"id":"fr_apparaitre_verb","lex":true,"fr":"apparaître","en":"to appear","ipa":"/a.pa.ʁɛtʁ/","say":"ah-pah-REHTR","cefr":"A1","ex":["Le soleil apparaît derrière les nuages.","The sun appears from behind the clouds."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_figurer_verb","fr":"figurer","hw":"figurer","en":"to appear; to imagine","note":"Figurer is to be listed or to imagine, not to come into sight. Apparaître is to come into view.","at":["st_reflets","st_reflets"]},{"to":"fr_paraitre_verb","fr":"paraître","hw":"paraître","en":"to appear","note":"Paraître is to seem, or to appear in print. Apparaître is to come into view.","at":null,"lex":true,"examples":[{"who":"paraître","fr":"Il paraît content.","en":"He seems happy."},{"who":"apparaître","fr":"Le soleil apparaît.","en":"The sun comes into view."}]}]},"fr_apporter_verb":{"id":"fr_apporter_verb","lex":true,"fr":"apporter","en":"to bring","ipa":"/a.pɔʁ.te/","say":"ah-por-TAY","cefr":"A1","ex":["Apporte-moi un verre d'eau, s'il te plaît.","Bring me a glass of water, please."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_amener_verb","fr":"amener","hw":"amener","en":"to bring","note":"Amener is usual for a person or an animal. Apporter is usual for a thing you carry.","at":null,"lex":true,"examples":[{"who":"apporter","fr":"J'apporte le dessert.","en":"I'm bringing dessert."},{"who":"amener","fr":"J'amène mon frère.","en":"I'm bringing my brother."}]},{"to":"fr_emporter_verb","fr":"emporter","hw":"emporter","en":"to take away","note":"Emporter is to take a thing away. Apporter is to bring a thing here.","at":null,"lex":true}]},"fr_approcher_verb":{"id":"fr_approcher_verb","lex":true,"fr":"approcher","en":"to approach","ipa":"/a.pʁɔ.ʃe/","say":"ah-proh-SHAY","cefr":"A1","ex":["Approche, je vais te montrer.","Come closer, I'll show you."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_aborder_verb","fr":"aborder","hw":"aborder","en":"to approach; to tackle","note":"Aborder is to approach a person or a subject, or to reach shore. Approcher is to come nearer.","at":null,"lex":true}]},"fr_attaque_noun":{"id":"fr_attaque_noun","lex":true,"fr":"attaque","en":"attack","ipa":"/a.tak/","say":"ah-TAHK","cefr":"B1","ex":["L'équipe prépare une attaque rapide.","The team prepares a quick attack."],"noMnemonic":true,"g":"f","art":"l'","ind":"une","compares":[{"to":"fr_atteinte_noun","fr":"atteinte","hw":"l'atteinte","en":"attack","note":"Atteinte is a reaching, or harm that gets to something (une atteinte à). Attaque is an assault.","at":null,"lex":true}]},"fr_atteinte_noun":{"id":"fr_atteinte_noun","lex":true,"fr":"atteinte","en":"attack","ipa":"/a.tɛ̃t/","say":"ah-TANT","cefr":"B2","ex":["Ces paroles sont une atteinte à sa réputation.","These words are an attack on his reputation."],"noMnemonic":true,"g":"f","art":"l'","ind":"une","compares":[{"to":"fr_attaque_noun","fr":"attaque","hw":"l'attaque","en":"attack","note":"Attaque is an attack. Atteinte is not that assault: it is the fact of reaching something, or damage done to it.","at":null,"lex":true}]},"fr_avouer_verb":{"id":"fr_avouer_verb","lex":true,"fr":"avouer","en":"to admit","ipa":"/a.vwe/","say":"ah-VWAY","cefr":"A2","ex":["Il avoue qu'il a cassé le vase.","He admits that he broke the vase."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_admettre_verb","fr":"admettre","hw":"admettre","en":"to admit","note":"Admettre is to admit that something is true, or to let someone in. Avouer is to confess.","at":null,"lex":true}]},"fr_batir_verb":{"id":"fr_batir_verb","lex":true,"fr":"bâtir","en":"to build; to construct; to build up","ipa":"/ba.tiʁ/","say":"bah-TEER","cefr":"B2","ex":["Ils ont bâti leur maison eux-mêmes.","They built their house themselves."],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_construire_verb","fr":"construire","hw":"construire","en":"to build","note":"Construire is the ordinary word. Bâtir is close to it, a little more formal.","at":null,"lex":true}]},"fr_bosser_verb":{"id":"fr_bosser_verb","lex":true,"fr":"bosser","en":"to work (informal)","ipa":"/bɔ.se/","say":"boh-SAY","cefr":"B1","ex":["Je bosse tard ce soir.","I'm working late tonight."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_travailler_verb","fr":"travailler","hw":"travailler","en":"to work","note":"Travailler is the ordinary word. Bosser is informal.","at":null,"lex":true}]},"fr_bouffer_verb":{"id":"fr_bouffer_verb","lex":true,"fr":"bouffer","en":"to eat, to scoff (informal)","ipa":"/bu.fe/","say":"boo-FAY","cefr":"B1","ex":["On a bien bouffé chez Paul hier soir.","We ate really well at Paul's last night."],"noMnemonic":true,"note":"Informal and a bit rude: fine among friends, but avoid it in polite or formal settings.","verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_manger_verb","fr":"manger","hw":"manger","en":"to eat","note":"Manger is the ordinary word. Bouffer is very informal.","at":null,"lex":true}]},"fr_bouger_verb":{"id":"fr_bouger_verb","lex":true,"fr":"bouger","en":"to move","ipa":"/bu.ʒe/","say":"boo-ZHAY","cefr":"A2","ex":["Ne bouge pas, je prends une photo.","Don't move, I'm taking a photo."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_deplacer_verb","fr":"déplacer","hw":"déplacer","en":"to move","note":"Déplacer is to move something from one place to another. Bouger is to move or to budge.","at":null,"lex":true},{"to":"fr_emouvoir_verb","fr":"émouvoir","hw":"émouvoir","en":"to move (emotionally)","note":"Émouvoir is to move someone emotionally. Bouger is to move physically.","at":["st_bagages","demenageurs"]},{"to":"fr_mouvoir_verb","fr":"mouvoir","hw":"mouvoir","en":"to move","note":"Mouvoir is a formal verb for to move. Bouger is the ordinary word.","at":["st_bagages","demenageurs"]}]},"fr_bouquiner_verb":{"id":"fr_bouquiner_verb","lex":true,"fr":"bouquiner","en":"to read (informal)","ipa":"/bu.ki.ne/","say":"boo-kee-NAY","cefr":"C2","ex":["Il aime bouquiner au lit.","He likes reading in bed."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_lire_verb","fr":"lire","hw":"lire","en":"to read","note":"Lire is the ordinary word. Bouquiner is informal.","at":["kiosque","kiosque"]}]},"fr_briser_verb":{"id":"fr_briser_verb","lex":true,"fr":"briser","en":"to break","ipa":"/bʁi.ze/","say":"bree-ZAY","cefr":"A2","ex":["Le vent a brisé la fenêtre.","The wind broke the window."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_casser_verb","fr":"casser","hw":"casser","en":"to break","note":"Casser is the everyday word. Briser is harsher: to shatter.","at":["st_porteurs","st_porteurs"]},{"to":"fr_rompre_verb","fr":"rompre","hw":"rompre","en":"to break","note":"Rompre is often to break off a bond or an agreement. Briser is to shatter something.","at":null,"lex":true}]},"fr_buanderie_noun":{"id":"fr_buanderie_noun","lex":true,"fr":"buanderie","en":"laundry","ipa":"/bɥɑ̃.dʁi/","say":"bwahn-duh-REE","cefr":"C2","ex":["La machine à laver est dans la buanderie.","The washing machine is in the laundry room."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_lessive_noun","fr":"lessive","hw":"la lessive","en":"laundry; washing powder","note":"Lessive is the washing powder or the act of washing clothes. Buanderie is the laundry room.","at":null,"lex":true}]},"fr_cacher_verb":{"id":"fr_cacher_verb","lex":true,"fr":"cacher","en":"to hide","ipa":"/ka.ʃe/","say":"kah-SHAY","cefr":"A1","ex":["Le chat se cache sous le lit.","The cat hides under the bed."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_planquer_verb","fr":"planquer","hw":"planquer","en":"to hide; to spy, to snoop","note":"Planquer is informal for to hide. Cacher is the ordinary word.","at":null,"lex":true}]},"fr_comedien_noun":{"id":"fr_comedien_noun","lex":true,"fr":"comédien","en":"actor","ipa":"/kɔ.me.djɛ̃/","say":"koh-may-DYAN","cefr":"B1","ex":["Ce comédien joue au théâtre.","This actor performs in the theater."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_acteur_noun","fr":"acteur","hw":"l'acteur","en":"actor","note":"Acteur is an actor. Comédien is an actor too, with a stage flavor.","at":["theatre","scene"]}]},"fr_commande_noun":{"id":"fr_commande_noun","lex":true,"fr":"commande","en":"order (what you ask for)","ipa":"/kɔ.mɑ̃d/","say":"koh-MAHND","cefr":"B1","ex":["Le serveur prend notre commande.","The waiter takes our order."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_ordre_noun","fr":"ordre","hw":"l'ordre","en":"order","note":"Ordre is a command or an arrangement. Commande is an order for goods or a meal.","at":["gare","aiguillage"]}]},"fr_concilier_verb":{"id":"fr_concilier_verb","lex":true,"fr":"concilier","en":"to reconcile; to conciliate","ipa":"/kɔ̃.si.lje/","say":"kohn-see-LYAY","cefr":"C1","ex":["Elle concilie travail et vie de famille.","She balances work and family life."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_reconcilier_verb","fr":"réconcilier","hw":"réconcilier","en":"to reconcile; to reconcile, to match up","note":"Réconcilier brings people back together after a quarrel. Concilier makes opposing people or ideas compatible. Concilier is also used for people who disagree, so it is not only for ideas.","at":null,"lex":true}]},"fr_connaitre_verb":{"id":"fr_connaitre_verb","lex":true,"fr":"connaître","en":"to know (be familiar with)","ipa":"/kɔ.nɛtʁ/","say":"koh-NEHTR","cefr":"A1","ex":["Tu connais ce restaurant ?","Do you know this restaurant?"],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_savoir_verb","fr":"savoir","hw":"savoir","en":"to know (facts, how to)","note":"Savoir is to know a fact or how to do something. Connaître is to be familiar with someone or something.","at":null,"lex":true,"examples":[{"who":"savoir","fr":"Je sais nager.","en":"I know how to swim."},{"who":"connaître","fr":"Je connais Marie.","en":"I know Marie."}]}]},"fr_construire_verb":{"id":"fr_construire_verb","lex":true,"fr":"construire","en":"to build","ipa":"/kɔ̃s.tʁɥiʁ/","say":"kohns-TRWEER","cefr":"A1","ex":["Ils construisent une nouvelle école.","They are building a new school."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_batir_verb","fr":"bâtir","hw":"bâtir","en":"to build; to construct; to build up","note":"Bâtir is to build, a bit more formal or figurative than construire. Construire is the ordinary word.","at":null,"lex":true}]},"fr_crainte_noun":{"id":"fr_crainte_noun","lex":true,"fr":"crainte","en":"fear","ipa":"/kʁɛ̃t/","say":"KRANT","cefr":"B1","ex":["Il parle sans crainte.","He speaks without fear."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_peur_noun","fr":"peur","hw":"la peur","en":"fear","note":"Peur is fear. Crainte is a more formal worry that something may happen.","at":null,"lex":true}]},"fr_croire_verb":{"id":"fr_croire_verb","lex":true,"fr":"croire","en":"to believe","ipa":"/kʁwaʁ/","say":"KRWAHR","cefr":"A1","ex":["Je crois qu'il va pleuvoir.","I think it's going to rain."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_penser_verb","fr":"penser","hw":"penser","en":"to think","note":"Penser is to think, to use your mind. Croire is to believe that something is true, or to believe a person.","at":null,"lex":true,"examples":[{"who":"croire","fr":"Je crois ce qu'il dit.","en":"I believe what he says."},{"who":"penser","fr":"Je pense que tu as raison.","en":"I think you are right."}]}]},"fr_croiser_verb":{"id":"fr_croiser_verb","lex":true,"fr":"croiser","en":"to cross","ipa":"/kʁwa.ze/","say":"krwah-ZAY","cefr":"A2","ex":["J'ai croisé ton frère dans la rue.","I bumped into your brother in the street."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_traverser_verb","fr":"traverser","hw":"traverser","en":"to cross","note":"Traverser is to go across, from one side to the other. Croiser is to cross two things, or to pass someone coming the other way.","at":null,"lex":true}]},"fr_cuisiner_verb":{"id":"fr_cuisiner_verb","lex":true,"fr":"cuisiner","en":"to cook (make a meal)","ipa":"/kɥi.zi.ne/","say":"kwee-zee-NAY","cefr":"B2","ex":["Mon frère adore cuisiner pour ses amis.","My brother loves cooking for his friends."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_cuire_verb","fr":"cuire","hw":"cuire","en":"to cook (with heat)","note":"Cuire is cooking by heat. Cuisiner is preparing a meal.","at":["boulangerie","fournil"],"examples":[{"who":"cuire","fr":"Le poulet cuit.","en":"The chicken is cooking."},{"who":"cuisiner","fr":"Je cuisine ce soir.","en":"I'm cooking tonight."}]}]},"fr_decliner_verb":{"id":"fr_decliner_verb","lex":true,"fr":"décliner","en":"to weaken; to enumerate","ipa":"/de.kli.ne/","say":"day-klee-NAY","cefr":"B2","ex":["Le jour décline vers six heures.","The daylight fades at around six."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_affaiblir_verb","fr":"affaiblir","hw":"affaiblir","en":"to weaken; to weaken, to become weaker","note":"Affaiblir makes something weaker. Décliner is to be on the way down, or to decline an offer in another sense of the verb.","at":null,"lex":true}]},"fr_deplacer_verb":{"id":"fr_deplacer_verb","lex":true,"fr":"déplacer","en":"to move","ipa":"/de.pla.se/","say":"day-plah-SAY","cefr":"A2","ex":["Aide-moi à déplacer la table.","Help me move the table."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_bouger_verb","fr":"bouger","hw":"bouger","en":"to move","note":"Bouger is to move yourself or to budge. Déplacer is to shift something else.","at":null,"lex":true}]},"fr_dessiner_verb":{"id":"fr_dessiner_verb","lex":true,"fr":"dessiner","en":"to draw","ipa":"/de.si.ne/","say":"day-see-NAY","cefr":"A1","ex":["Ma fille dessine un chat.","My daughter is drawing a cat."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_tracer_verb","fr":"tracer","hw":"tracer","en":"to draw","note":"Tracer is to trace or draw a line. Dessiner is to draw a picture.","at":null,"lex":true}]},"fr_detester_verb":{"id":"fr_detester_verb","lex":true,"fr":"détester","en":"to hate, to detest","ipa":"/de.tɛs.te/","say":"day-tehs-TAY","cefr":"A1","ex":["Je déteste me lever tôt.","I hate getting up early."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_hair_verb","fr":"haïr","hw":"haïr","en":"to hate","note":"Haïr is stronger: to hate. Détester is to dislike strongly, the everyday word.","at":null,"lex":true}]},"fr_devoir_verb":{"id":"fr_devoir_verb","lex":true,"fr":"devoir","en":"must, to have to","ipa":"/də.vwaʁ/","say":"duh-VWAHR","cefr":"A1","ex":["Je dois partir maintenant.","I must leave now."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_falloir_verb","fr":"falloir","hw":"falloir","en":"to be necessary (il faut)","note":"Falloir is impersonal: il faut. It says something is necessary. Devoir is a personal verb: someone must, or someone owes.","at":null,"lex":true,"examples":[{"who":"devoir","fr":"Je dois partir.","en":"I have to leave."},{"who":"falloir","fr":"Il faut partir.","en":"It is necessary to leave."}]}]},"fr_durant_prep":{"id":"fr_durant_prep","lex":true,"fr":"durant","en":"during, throughout","ipa":"/dy.ʁɑ̃/","say":"dew-RAHN","cefr":"B1","ex":["Il a plu durant toute la nuit.","It rained all through the night."],"noMnemonic":true,"adv":true,"gramLine":"preposition · invariable","compares":[{"to":"fr_pendant_prep","fr":"pendant","hw":"pendant","en":"during; for (a length of time)","note":"Pendant is the ordinary word. With a length of time it means for. Durant is during or throughout, a bit more formal.","at":["ecole","preau"],"examples":[{"who":"pendant","fr":"pendant deux heures","en":"for two hours"},{"who":"durant","fr":"durant toute la nuit","en":"all through the night"}]}]},"fr_echapper_verb":{"id":"fr_echapper_verb","lex":true,"fr":"échapper","en":"to escape","ipa":"/e.ʃa.pe/","say":"ay-shah-PAY","cefr":"A2","ex":["Le chien s'est échappé du jardin.","The dog escaped from the garden."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_evader_verb","fr":"évader","hw":"évader","en":"to escape","note":"S'évader is to escape from a place that holds you, such as a prison. Échapper is to escape or to avoid, more broadly.","at":null,"lex":true}]},"fr_eclater_verb":{"id":"fr_eclater_verb","lex":true,"fr":"éclater","en":"to burst","ipa":"/e.kla.te/","say":"ay-klah-TAY","cefr":"A2","ex":["Le ballon a éclaté.","The balloon burst."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_crever_verb","fr":"crever","hw":"crever","en":"to burst; to die (informal)","note":"Éclater is to burst. Crever is to burst, or, informally, to die.","at":["st_campeur","pinces"]}]},"fr_emmener_verb":{"id":"fr_emmener_verb","lex":true,"fr":"emmener","en":"to take (someone) along","ipa":"/ɑ̃.m(ə).ne/","say":"ahn-muh-NAY","cefr":"A1","ex":["J'emmène les enfants à l'école.","I take the children to school."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_amener_verb","fr":"amener","hw":"amener","en":"to bring","note":"Amener is to bring a person here. Emmener is to take a person away.","at":null,"lex":true},{"to":"fr_emporter_verb","fr":"emporter","hw":"emporter","en":"to take away","note":"Emporter is to take a thing away. Emmener is to take a person or an animal along.","at":null,"lex":true,"examples":[{"who":"emporter","fr":"J'emporte un parapluie.","en":"I'm taking an umbrella."},{"who":"emmener","fr":"Elle emmène les enfants au parc.","en":"She is taking the children to the park."}]}]},"fr_emplir_verb":{"id":"fr_emplir_verb","lex":true,"fr":"emplir","en":"to fill","ipa":"/ɑ̃.pliʁ/","say":"ahn-PLEER","cefr":"B1","ex":["La salle s'emplit de monde à midi.","The room fills with people at noon."],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_remplir_verb","fr":"remplir","hw":"remplir","en":"to fill (up)","note":"Remplir is ordinary. Emplir is literary.","at":null,"lex":true}]},"fr_emporter_verb":{"id":"fr_emporter_verb","lex":true,"fr":"emporter","en":"to take away","ipa":"/ɑ̃.pɔʁ.te/","say":"ahn-por-TAY","cefr":"A2","ex":["N'oublie pas d'emporter ton parapluie.","Don't forget to take your umbrella."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_apporter_verb","fr":"apporter","hw":"apporter","en":"to bring","note":"Apporter is to bring a thing here. Emporter is to take a thing away.","at":null,"lex":true},{"to":"fr_emmener_verb","fr":"emmener","hw":"emmener","en":"to take (someone) along","note":"Emmener is to take a person or an animal along. Emporter is to take a thing away.","at":null,"lex":true,"examples":[{"who":"emporter","fr":"J'emporte un parapluie.","en":"I'm taking an umbrella."},{"who":"emmener","fr":"Elle emmène les enfants au parc.","en":"She is taking the children to the park."}]}]},"fr_enfuir_verb":{"id":"fr_enfuir_verb","lex":true,"fr":"enfuir","en":"to flee (s'enfuir)","ipa":"/ɑ̃.fɥiʁ/","say":"ahn-FWEER","cefr":"A2","ex":["Le chat s'est enfui dans le jardin.","The cat ran off into the garden."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_fuir_verb","fr":"fuir","hw":"fuir","en":"to flee","note":"Fuir is to flee or to shun. S'enfuir is to take flight.","at":null,"lex":true}]},"fr_enseigner_verb":{"id":"fr_enseigner_verb","lex":true,"fr":"enseigner","en":"to teach","ipa":"/ɑ̃.sɛ.ɲe/","say":"ahn-say-NYAY","cefr":"B1","ex":["Elle enseigne le français.","She teaches French."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_apprendre_verb","fr":"apprendre","hw":"apprendre","en":"to learn; to teach","note":"Apprendre is first to learn. Enseigner is only the teaching side. Apprendre quelque chose à quelqu'un is also to teach.","at":["ecole","classe"],"examples":[{"who":"apprendre","fr":"J'apprends le piano.","en":"I'm learning piano."},{"who":"enseigner","fr":"Elle enseigne le piano.","en":"She teaches piano."}]}]},"fr_entendre_verb":{"id":"fr_entendre_verb","lex":true,"fr":"entendre","en":"to hear","ipa":"/ɑ̃.tɑ̃dʁ/","say":"ahn-TAHNDR","cefr":"A1","ex":["J'entends de la musique.","I can hear music."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_ecouter_verb","fr":"écouter","hw":"écouter","en":"to listen","note":"Écouter is to listen on purpose. The TLFi sets it against entendre, the way regarder stands against voir. Entendre is to hear, whether or not you were trying.","at":["ecole","classe"],"examples":[{"who":"entendre","fr":"J'entends la pluie.","en":"I hear the rain."},{"who":"écouter","fr":"J'écoute la radio.","en":"I'm listening to the radio."}]}]},"fr_envers_prep":{"id":"fr_envers_prep","lex":true,"fr":"envers","en":"toward (feelings or attitude)","ipa":"/ɑ̃.vɛʁ/","say":"ahn-VEHR","cefr":"B1","ex":["Il est très gentil envers ses voisins.","He's very kind toward his neighbors."],"noMnemonic":true,"adv":true,"gramLine":"preposition · invariable","compares":[{"to":"fr_vers_prep","fr":"vers","hw":"vers","en":"toward; around (a time)","note":"Vers is toward a place or about a time. Envers is how you act toward someone.","at":null,"lex":true,"examples":[{"who":"vers","fr":"Je vais vers la gare.","en":"I'm heading toward the station."},{"who":"envers","fr":"Il est gentil envers elle.","en":"He is kind toward her."}]}]},"fr_epouser_verb":{"id":"fr_epouser_verb","lex":true,"fr":"épouser","en":"to marry","ipa":"/e.pu.ze/","say":"ay-poo-ZAY","cefr":"A1","ex":["Il va épouser sa fiancée en mai.","He is going to marry his fiancée in May."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_marier_verb","fr":"marier","hw":"marier","en":"to marry (se marier = get married)","note":"Se marier is to get married. Épouser is to marry someone.","at":null,"lex":true,"examples":[{"who":"marier","fr":"Ils se marient en juin.","en":"They are getting married in June."},{"who":"épouser","fr":"Elle épouse Paul.","en":"She is marrying Paul."}]}]},"fr_eprouver_verb":{"id":"fr_eprouver_verb","lex":true,"fr":"éprouver","en":"to feel; to test","ipa":"/e.pʁu.ve/","say":"ay-proo-VAY","cefr":"B1","ex":["Il éprouve une grande joie.","He feels great joy."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_ressentir_verb","fr":"ressentir","hw":"ressentir","en":"to feel","note":"Ressentir is to feel an emotion or a sensation. Éprouver is to feel something strongly, or to put something to the test.","at":["st_soupirs","applaudissements"]}]},"fr_essayer_verb":{"id":"fr_essayer_verb","lex":true,"fr":"essayer","en":"to try","ipa":"/e.sɛ.je/","say":"ay-say-YAY","cefr":"A1","ex":["Je peux essayer cette veste ?","Can I try on this jacket?"],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_tacher_verb","fr":"tâcher","hw":"tâcher","en":"to try","note":"Tâcher de is to make an effort to do something. Essayer is the everyday word for to try.","at":["st_departs","galopins"]},{"to":"fr_tenter_verb","fr":"tenter","hw":"tenter","en":"to try; to tempt","note":"Tenter is to try, a bit more formal, and it also means to tempt. Essayer is the everyday word for to try.","at":null,"lex":true}]},"fr_etonner_verb":{"id":"fr_etonner_verb","lex":true,"fr":"étonner","en":"to surprise","ipa":"/e.tɔ.ne/","say":"ay-toh-NAY","cefr":"A2","ex":["Sa réponse m'étonne.","His answer surprises me."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_surprendre_verb","fr":"surprendre","hw":"surprendre","en":"to surprise; to catch out","note":"Surprendre is to surprise or to catch. Étonner is to amaze.","at":null,"lex":true}]},"fr_evader_verb":{"id":"fr_evader_verb","lex":true,"fr":"évader","en":"to escape","ipa":"/e.va.de/","say":"ay-vah-DAY","cefr":"B2","ex":["Le perroquet s'est évadé de sa cage.","The parrot escaped from its cage."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_echapper_verb","fr":"échapper","hw":"échapper","en":"to escape","note":"Échapper is to get away or to avoid. S'évader is to break out of confinement.","at":null,"lex":true}]},"fr_evasion_noun":{"id":"fr_evasion_noun","lex":true,"fr":"évasion","en":"escape; escapism","ipa":"/e.va.zjɔ̃/","say":"ay-vah-ZYOHN","cefr":"B2","ex":["La lecture est pour moi une évasion.","Reading is an escape for me."],"noMnemonic":true,"g":"f","art":"l'","ind":"une","compares":[{"to":"fr_fuite_noun","fr":"fuite","hw":"la fuite","en":"escape; leak","note":"Fuite is running away, or a leak. Évasion is escaping from a place that held you, or escaping into a fantasy.","at":null,"lex":true}]},"fr_exiger_verb":{"id":"fr_exiger_verb","lex":true,"fr":"exiger","en":"to demand","ipa":"/ɛɡ.zi.ʒe/","say":"ehg-zee-ZHAY","cefr":"A2","ex":["Le professeur exige le silence.","The teacher demands silence."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_revendiquer_verb","fr":"revendiquer","hw":"revendiquer","en":"to demand; to claim","note":"Revendiquer is to claim something as yours or as your due. Exiger is to insist that something be done.","at":["st_ecus","marchandage"]}]},"fr_experience_noun":{"id":"fr_experience_noun","lex":true,"fr":"expérience","en":"experience; experiment","ipa":"/ɛk.spe.ʁjɑ̃s/","say":"ehk-spay-RYAHNS","cefr":"A2","ex":["Elle a beaucoup d'expérience.","She has a lot of experience."],"noMnemonic":true,"g":"f","art":"l'","ind":"une","compares":[{"to":"fr_vecu_noun","fr":"vécu","hw":"le vécu","en":"experience; inner life","note":"Vécu is what you have lived through. Expérience is experience, and it is also an experiment.","at":["couture","malle"]}]},"fr_falloir_verb":{"id":"fr_falloir_verb","lex":true,"fr":"falloir","en":"to be necessary (il faut)","ipa":"/fa.lwaʁ/","say":"fah-LWAHR","cefr":"A1","ex":["Il faut partir maintenant.","We have to leave now."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_devoir_verb","fr":"devoir","hw":"devoir","en":"must, to have to","note":"Devoir says who must do something, or who owes something. Falloir has no person of its own: il faut.","at":null,"lex":true,"examples":[{"who":"devoir","fr":"Je dois partir.","en":"I have to leave."},{"who":"falloir","fr":"Il faut partir.","en":"It is necessary to leave."}]}]},"fr_fierte_noun":{"id":"fr_fierte_noun","lex":true,"fr":"fierté","en":"pride","ipa":"/fjɛʁ.te/","say":"fyehr-TAY","cefr":"B1","ex":["Elle montre son diplôme avec fierté.","She shows her diploma with pride."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_orgueil_noun","fr":"orgueil","hw":"l'orgueil","en":"pride","note":"Orgueil is haughtiness. Fierté is a proud, good feeling.","at":null,"lex":true}]},"fr_fric_noun":{"id":"fr_fric_noun","lex":true,"fr":"fric","en":"money (informal)","ipa":"/fʁik/","say":"FREEK","cefr":"B1","ex":["Il n'a plus de fric.","He has no more cash."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_argent_noun","fr":"argent","hw":"l'argent","en":"money; silver","note":"Argent is the ordinary word for money. Fric is casual slang.","at":["banque","banque"]}]},"fr_fuir_verb":{"id":"fr_fuir_verb","lex":true,"fr":"fuir","en":"to flee","ipa":"/fɥiʁ/","say":"FWEER","cefr":"A2","ex":["Les animaux fuient devant le feu.","The animals flee from the fire."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_enfuir_verb","fr":"enfuir","hw":"enfuir","en":"to flee (s'enfuir)","note":"S'enfuir is to run away. Fuir is to flee a place or to avoid something.","at":null,"lex":true}]},"fr_fuite_noun":{"id":"fr_fuite_noun","lex":true,"fr":"fuite","en":"escape; leak","ipa":"/fɥit/","say":"FWEET","cefr":"B1","ex":["Il y a une fuite d'eau dans la cuisine.","There's a water leak in the kitchen."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_evasion_noun","fr":"évasion","hw":"l'évasion","en":"escape; escapism","note":"Évasion is a breakout, or an escape from a hard reality. Fuite is flight from a threat, or a leak.","at":null,"lex":true}]},"fr_gagner_verb":{"id":"fr_gagner_verb","lex":true,"fr":"gagner","en":"to win; to earn","ipa":"/ɡa.ɲe/","say":"gah-NYAY","cefr":"A1","ex":["Notre équipe a gagné le match.","Our team won the match."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_remporter_verb","fr":"remporter","hw":"remporter","en":"to win","note":"Remporter is to win a match, a prize, or a victory. Gagner is to win, and also to earn money.","at":null,"lex":true}]},"fr_hair_verb":{"id":"fr_hair_verb","lex":true,"fr":"haïr","en":"to hate","ipa":"/a.iʁ/","say":"ah-EER","cefr":"B1","ex":["Il hait le mensonge.","He hates lying."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_detester_verb","fr":"détester","hw":"détester","en":"to hate, to detest","note":"Détester is the everyday word for to really dislike. Haïr is to hate.","at":null,"lex":true}]},"fr_informer_verb":{"id":"fr_informer_verb","lex":true,"fr":"informer","en":"to inform","ipa":"/ɛ̃.fɔʁ.me/","say":"an-for-MAY","cefr":"A2","ex":["Nous vous informons que le train est en retard.","We inform you that the train is late."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_renseigner_verb","fr":"renseigner","hw":"renseigner","en":"to inform","note":"Renseigner is to give someone the information they asked for. Informer is to inform, to tell people.","at":null,"lex":true}]},"fr_inquiet_adj":{"id":"fr_inquiet_adj","lex":true,"fr":"inquiet","en":"worried","ipa":"/ɛ̃.kjɛ/","say":"an-KYEH","cefr":"A2","ex":["Je suis inquiet pour toi.","I'm worried about you."],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_soucieux_adj","fr":"soucieux","hw":"soucieux","en":"worried; nervous, hesitant","note":"Soucieux is worried in a preoccupied way, or careful about something. Inquiet is worried or anxious.","at":null,"lex":true}]},"fr_inquietude_noun":{"id":"fr_inquietude_noun","lex":true,"fr":"inquiétude","en":"worry","ipa":"/ɛ̃.kje.tyd/","say":"an-kyay-TEWD","cefr":"B1","ex":["Sa mère ne cache pas son inquiétude.","His mother doesn't hide her worry."],"noMnemonic":true,"g":"f","art":"l'","ind":"une","compares":[{"to":"fr_souci_noun","fr":"souci","hw":"le souci","en":"worry","note":"Souci is a worry. Inquiétude is the anxious feeling.","at":null,"lex":true}]},"fr_interroger_verb":{"id":"fr_interroger_verb","lex":true,"fr":"interroger","en":"to question, interrogate","ipa":"/ɛ̃.tɛ.ʁɔ.ʒe/","say":"an-teh-roh-ZHAY","cefr":"A1","ex":["Le professeur interroge un élève.","The teacher questions a student."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_questionner_verb","fr":"questionner","hw":"questionner","en":"to question, interrogate; to call into question","note":"Questionner is to question, and it can mean to call into question. Interroger is to question someone, as in class or an inquiry.","at":null,"lex":true}]},"fr_judiciaire_adj":{"id":"fr_judiciaire_adj","lex":true,"fr":"judiciaire","en":"judicial; forensic","ipa":"/ʒy.di.sjɛʁ/","say":"zhew-dee-SYEHR","cefr":"B2","ex":["Il y a une enquête judiciaire.","There's a judicial investigation."],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_juridique_adj","fr":"juridique","hw":"juridique","en":"judicial; law; legal","note":"Juridique is about the law as a system of rules. Judiciaire is about the courts and how a case is judged.","at":null,"lex":true}]},"fr_juridique_adj":{"id":"fr_juridique_adj","lex":true,"fr":"juridique","en":"judicial; law; legal","ipa":"/ʒy.ʁi.dik/","say":"zhew-ree-DEEK","cefr":"B2","ex":["Il demande un conseil juridique.","He asks for legal advice."],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_judiciaire_adj","fr":"judiciaire","hw":"judiciaire","en":"judicial; forensic","note":"Judiciaire belongs to the courts. Juridique belongs to the law.","at":null,"lex":true}]},"fr_laisser_verb":{"id":"fr_laisser_verb","lex":true,"fr":"laisser","en":"to leave; to let","ipa":"/lɛ.se/","say":"lay-SAY","cefr":"A1","ex":["Laisse la porte ouverte.","Leave the door open."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_partir_verb","fr":"partir","hw":"partir","en":"to leave","note":"Partir is to go away. Laisser is to leave something or someone behind, or to allow it.","at":["st_departs","st_departs"],"examples":[{"who":"laisser","fr":"J'ai laissé mes clés à la maison.","en":"I left my keys at home."}]},{"to":"fr_quitter_verb","fr":"quitter","hw":"quitter","en":"to leave","note":"Quitter is to leave a person or a place. Laisser is to leave something behind, or to let.","at":["st_departs","grimpeurs"]}]},"fr_lessive_noun":{"id":"fr_lessive_noun","lex":true,"fr":"lessive","en":"laundry; washing powder","ipa":"/le.siv/","say":"lay-SEEV","cefr":"B2","ex":["Je fais la lessive le samedi.","I do the laundry on Saturdays."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_buanderie_noun","fr":"buanderie","hw":"la buanderie","en":"laundry","note":"Buanderie is the room where the wash is done. Lessive is the detergent, or the wash itself.","at":null,"lex":true}]},"fr_manche_noun_m":{"id":"fr_manche_noun_m","lex":true,"fr":"manche","en":"handle","ipa":"/mɑ̃ʃ/","say":"MAHNSH","cefr":"B1","ex":["Le manche de la casserole est chaud.","The saucepan handle is hot."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_poignee_noun","fr":"poignée","hw":"la poignée","en":"handle; handful","note":"Poignée is a handle you grip, like a door handle, or a handful. The masculine manche is the handle of a tool.","at":["maison","jardin_facade"]}]},"fr_manger_verb":{"id":"fr_manger_verb","lex":true,"fr":"manger","en":"to eat","ipa":"/mɑ̃.ʒe/","say":"mahn-ZHAY","cefr":"A1","ex":["Nous mangeons à midi.","We eat at noon."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_bouffer_verb","fr":"bouffer","hw":"bouffer","en":"to eat, to scoff (informal)","note":"Bouffer is very informal for to eat. Manger is the ordinary word.","at":null,"lex":true}]},"fr_manquer_verb":{"id":"fr_manquer_verb","lex":true,"fr":"manquer","en":"to miss; to lack","ipa":"/mɑ̃.ke/","say":"mahn-KAY","cefr":"A1","ex":["Tu me manques beaucoup.","I miss you a lot."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_rater_verb","fr":"rater","hw":"rater","en":"to miss; to fail","note":"Rater is to miss or to fail, and it is a bit informal. Manquer is to miss a train or a person, or to lack.","at":["stade","stade"],"examples":[{"who":"manquer","fr":"Il manque du pain.","en":"There isn't enough bread."},{"who":"rater","fr":"Il a raté son examen.","en":"He failed his exam."}]}]},"fr_marcher_verb":{"id":"fr_marcher_verb","lex":true,"fr":"marcher","en":"to walk; to work (machine)","ipa":"/maʁ.ʃe/","say":"mahr-SHAY","cefr":"A1","ex":["Je marche jusqu'à l'école.","I walk to school."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_promener_verb","fr":"promener","hw":"promener","en":"to walk (se promener = go for a walk)","note":"Se promener is to go for a walk. Promener is also to walk a dog. Marcher is to walk.","at":null,"lex":true}]},"fr_marier_verb":{"id":"fr_marier_verb","lex":true,"fr":"marier","en":"to marry (se marier = get married)","ipa":"/ma.ʁje/","say":"mah-RYAY","cefr":"A1","ex":["Ils se marient l'été prochain.","They're getting married next summer."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_epouser_verb","fr":"épouser","hw":"épouser","en":"to marry","note":"Épouser takes the person you marry as a direct object. Se marier is to get married.","at":null,"lex":true,"examples":[{"who":"marier","fr":"Ils se marient en juin.","en":"They are getting married in June."},{"who":"épouser","fr":"Elle épouse Paul.","en":"She is marrying Paul."}]}]},"fr_marrant_adj":{"id":"fr_marrant_adj","lex":true,"fr":"marrant","en":"funny","ipa":"/ma.ʁɑ̃/","say":"mah-RAHN","cefr":"B1","ex":["Ton frère est vraiment marrant.","Your brother is really funny."],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_drole_adj","fr":"drôle","hw":"drôle","en":"funny","note":"Drôle is funny, or strange in un drôle de. Marrant is the informal word for funny.","at":["theatre","salle"]}]},"fr_meprise_noun":{"id":"fr_meprise_noun","lex":true,"fr":"méprise","en":"mistake","ipa":"/mepʁiz/","say":"may-PREEZ","cefr":"C2","ex":["Il y a eu une méprise sur la date.","There was a mistake about the date."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_faute_noun","fr":"faute","hw":"la faute","en":"mistake; fault","note":"Faute is a fault or a mistake. Méprise is taking one thing for another.","at":["pompiers","pompiers"]}]},"fr_muraille_noun":{"id":"fr_muraille_noun","lex":true,"fr":"muraille","en":"wall","ipa":"/my.ʁaj/","say":"mew-RAHY","cefr":"B2","ex":["La Grande Muraille de Chine est très longue.","The Great Wall of China is very long."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_mur_noun","fr":"mur","hw":"le mur","en":"wall","note":"Mur is an ordinary wall. Muraille is a rampart.","at":["maison","maison"]}]},"fr_nana_noun":{"id":"fr_nana_noun","lex":true,"fr":"nana","en":"girl (informal)","ipa":"/na.na/","say":"nah-NAH","cefr":"B2","ex":["Ma cousine est une nana très sympa.","My cousin is a really nice girl."],"noMnemonic":true,"note":"Informal slang for a girl or woman; can sound disrespectful, so avoid it in polite settings.","g":"f","art":"la","ind":"une","compares":[{"to":"fr_fille_noun","fr":"fille","hw":"la fille","en":"girl; daughter","note":"Fille is the ordinary word. Nana is informal.","at":["maison","famille"]}]},"fr_nombre_noun":{"id":"fr_nombre_noun","lex":true,"fr":"nombre","en":"number","ipa":"/nɔ̃bʁ/","say":"NOHNBR","cefr":"A1","ex":["Choisis un nombre entre un et dix.","Choose a number between one and ten."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_chiffre_noun","fr":"chiffre","hw":"le chiffre","en":"figure, digit","note":"Chiffre is a digit, from 0 to 9, or a figure people quote. Nombre is the whole number or the quantity.","at":["balance","balance"]},{"to":"fr_numero_noun","fr":"numéro","hw":"le numéro","en":"number; phone number","note":"Numéro is a label in a series. Nombre is how many, or a number in math.","at":["mairie","poste"],"examples":[{"who":"le numéro","fr":"Quel est ton numéro ?","en":"What is your number?"},{"who":"le nombre","fr":"Choisis un nombre entre un et dix.","en":"Pick a number between one and ten."}]}]},"fr_nourriture_noun":{"id":"fr_nourriture_noun","lex":true,"fr":"nourriture","en":"food","ipa":"/nu.ʁi.tyʁ/","say":"noo-ree-TEWR","cefr":"A2","ex":["La nourriture est délicieuse ici.","The food is delicious here."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_aliment_noun","fr":"aliment","hw":"l'aliment","en":"food","note":"Aliment is one food, an item you eat. Nourriture is food in general.","at":null,"lex":true},{"to":"fr_alimentation_noun","fr":"alimentation","hw":"l'alimentation","en":"food; diet","note":"Alimentation is diet, or the food supply. Nourriture is the food itself.","at":["maison","salle"]}]},"fr_ordonner_verb":{"id":"fr_ordonner_verb","lex":true,"fr":"ordonner","en":"to order","ipa":"/ɔʁ.dɔ.ne/","say":"or-doh-NAY","cefr":"B1","ex":["Le capitaine ordonne le départ.","The captain orders the departure."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_commander_verb","fr":"commander","hw":"commander","en":"to order","note":"Commander is to order goods, or to command. Ordonner is to order someone to act, or to put things in order.","at":["st_ecus","livreurs"]}]},"fr_orgueil_noun":{"id":"fr_orgueil_noun","lex":true,"fr":"orgueil","en":"pride","ipa":"/ɔʁ.ɡœj/","say":"or-GUHY","cefr":"B1","ex":["Son orgueil l'empêche de s'excuser.","His pride stops him from apologizing."],"noMnemonic":true,"g":"m","art":"l'","ind":"un","compares":[{"to":"fr_fierte_noun","fr":"fierté","hw":"la fierté","en":"pride","note":"Fierté is pride you can be glad of. Orgueil is pride as arrogance.","at":null,"lex":true}]},"fr_paraitre_verb":{"id":"fr_paraitre_verb","lex":true,"fr":"paraître","en":"to appear","ipa":"/pa.ʁɛtʁ/","say":"pah-REHTR","cefr":"A2","ex":["Il paraît fatigué ce matin.","He seems tired this morning."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_apparaitre_verb","fr":"apparaître","hw":"apparaître","en":"to appear","note":"Apparaître is to come into sight. Paraître is to seem, or to be published.","at":null,"lex":true,"examples":[{"who":"paraître","fr":"Il paraît content.","en":"He seems happy."},{"who":"apparaître","fr":"Le soleil apparaît.","en":"The sun comes into view."}]},{"to":"fr_figurer_verb","fr":"figurer","hw":"figurer","en":"to appear; to imagine","note":"Figurer is to appear on a list or in a group, or to imagine. Paraître is to seem, or to be published.","at":["st_reflets","st_reflets"]}]},"fr_parler_verb":{"id":"fr_parler_verb","lex":true,"fr":"parler","en":"to speak","ipa":"/paʁ.le/","say":"pahr-LAY","cefr":"A1","ex":["Je parle français et anglais.","I speak French and English."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_dire_verb","fr":"dire","hw":"dire","en":"to say","note":"Dire is to say specific words. Parler is to speak, often with no object, or parler de a topic.","at":["cafe","terrasse"],"examples":[{"who":"dire","fr":"Il dit bonjour.","en":"He says hello."},{"who":"parler","fr":"Il parle trop.","en":"He talks too much."}]},{"to":"fr_raconter_verb","fr":"raconter","hw":"raconter","en":"to tell","note":"Raconter is to tell a story, true or made up. Parler is to speak.","at":null,"lex":true,"examples":[{"who":"raconter","fr":"Raconte-moi ta journée.","en":"Tell me about your day."}]}]},"fr_paroi_noun":{"id":"fr_paroi_noun","lex":true,"fr":"paroi","en":"wall; inner wall, inside surface","ipa":"/pa.ʁwa/","say":"pah-RWAH","cefr":"B2","ex":["L'alpiniste grimpe la paroi rocheuse.","The climber scales the rock face."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_mur_noun","fr":"mur","hw":"le mur","en":"wall","note":"Mur is a building wall. Paroi is a side or an inner surface.","at":["maison","maison"]}]},"fr_parvenir_verb":{"id":"fr_parvenir_verb","lex":true,"fr":"parvenir","en":"to reach","ipa":"/paʁ.və.niʁ/","say":"pahr-vuh-NEER","cefr":"A2","ex":["Nous sommes parvenus au sommet.","We reached the summit."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_atteindre_verb","fr":"atteindre","hw":"atteindre","en":"to reach","note":"Atteindre is to reach. Parvenir is to succeed in getting there.","at":["st_croissance","transformistes"]}]},"fr_penser_verb":{"id":"fr_penser_verb","lex":true,"fr":"penser","en":"to think","ipa":"/pɑ̃.se/","say":"pahn-SAY","cefr":"A1","ex":["Je pense à toi.","I'm thinking of you."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_croire_verb","fr":"croire","hw":"croire","en":"to believe","note":"Croire is to hold something as true. Penser is to think, and penser que is an opinion, not necessarily a belief you would defend.","at":null,"lex":true,"examples":[{"who":"croire","fr":"Je crois ce qu'il dit.","en":"I believe what he says."},{"who":"penser","fr":"Je pense que tu as raison.","en":"I think you are right."}]},{"to":"fr_songer_verb","fr":"songer","hw":"songer","en":"to think, dream","note":"Songer is more literary: to have something in mind. Penser is the ordinary word for to think.","at":null,"lex":true}]},"fr_peur_noun":{"id":"fr_peur_noun","lex":true,"fr":"peur","en":"fear","ipa":"/pœʁ/","say":"PEUHR","cefr":"A1","ex":["J'ai peur du noir.","I'm afraid of the dark."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_crainte_noun","fr":"crainte","hw":"la crainte","en":"fear","note":"Crainte is more formal, often a worry about what might happen. Peur is fear, including a sudden fright.","at":null,"lex":true}]},"fr_plaisanterie_noun":{"id":"fr_plaisanterie_noun","lex":true,"fr":"plaisanterie","en":"joke","ipa":"/plɛ.zɑ̃.tʁi/","say":"pleh-zahn-tuh-REE","cefr":"B1","ex":["C'est une plaisanterie, ne t'inquiète pas.","It's a joke, don't worry."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_blague_noun","fr":"blague","hw":"la blague","en":"joke","note":"Blague is everyday. Plaisanterie is a little more formal.","at":["pavillons","pavillons"]}]},"fr_planquer_verb":{"id":"fr_planquer_verb","lex":true,"fr":"planquer","en":"to hide; to spy, to snoop","ipa":"/plɑ̃.ke/","say":"plahn-KAY","cefr":"B2","ex":["Il planque ses bonbons sous son lit.","He hides his candy under his bed."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_cacher_verb","fr":"cacher","hw":"cacher","en":"to hide","note":"Cacher is the ordinary word. Planquer is informal.","at":null,"lex":true}]},"fr_plat_noun":{"id":"fr_plat_noun","lex":true,"fr":"plat","en":"dish (a course or the plate it comes on)","ipa":"/pla/","say":"PLAH","cefr":"A1","ex":["Le serveur apporte le plat du jour.","The waiter brings the dish of the day."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_mets_noun","fr":"mets","hw":"le mets","en":"dish","note":"Mets is a prepared dish, a culinary or formal word. Plat is a dish or the course, and also the platter.","at":["maison","salle"]}]},"fr_prelever_verb":{"id":"fr_prelever_verb","lex":true,"fr":"prélever","en":"to take; to take out, withdraw","ipa":"/pʁel.ve/","say":"pray-luh-VAY","cefr":"B2","ex":["L'infirmière prélève un peu de sang.","The nurse takes a little blood."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_prendre_verb","fr":"prendre","hw":"prendre","en":"to take","note":"Prendre is the general word for to take. Prélever is to take a portion out of a whole, as a sample, a tax, or a deduction.","at":null,"lex":true}]},"fr_prendre_verb":{"id":"fr_prendre_verb","lex":true,"fr":"prendre","en":"to take","ipa":"/pʁɑ̃.dʁə/","say":"PRAHNDR","cefr":"A1","ex":["Je prends le bus pour aller au travail.","I take the bus to go to work."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_prelever_verb","fr":"prélever","hw":"prélever","en":"to take; to take out, withdraw","note":"Prélever takes a part out before the rest is used. Prendre is to take, in the broad sense.","at":null,"lex":true}]},"fr_prevenir_verb":{"id":"fr_prevenir_verb","lex":true,"fr":"prévenir","en":"to prevent; to notify","ipa":"/pʁev.niʁ/","say":"preh-vuh-NEER","cefr":"A2","ex":["Préviens-moi si tu es en retard.","Let me know if you're late."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_empecher_verb","fr":"empêcher","hw":"empêcher","en":"to prevent","note":"Empêcher is to prevent, or to keep someone from doing something. Prévenir is usually to let someone know ahead of time.","at":["st_croissance","point_final"]}]},"fr_promener_verb":{"id":"fr_promener_verb","lex":true,"fr":"promener","en":"to walk (se promener = go for a walk)","ipa":"/pʁɔm.ne/","say":"prom-NAY","cefr":"A1","ex":["Je promène mon chien le soir.","I walk my dog in the evening."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_marcher_verb","fr":"marcher","hw":"marcher","en":"to walk; to work (machine)","note":"Marcher is to walk. Promener is to take someone or a dog for a walk.","at":null,"lex":true}]},"fr_questionner_verb":{"id":"fr_questionner_verb","lex":true,"fr":"questionner","en":"to question, interrogate; to call into question","ipa":"/kɛs.tjɔ.ne/","say":"kehs-tyoh-NAY","cefr":"B2","ex":["Le professeur questionne les élèves.","The teacher questions the students."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_interroger_verb","fr":"interroger","hw":"interroger","en":"to question, interrogate","note":"Interroger is to put questions to someone. Questionner is close, and it can mean to challenge an idea.","at":null,"lex":true}]},"fr_raconter_verb":{"id":"fr_raconter_verb","lex":true,"fr":"raconter","en":"to tell","ipa":"/ʁa.kɔ̃.te/","say":"rah-kohn-TAY","cefr":"A1","ex":["Raconte-moi une histoire.","Tell me a story."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_dire_verb","fr":"dire","hw":"dire","en":"to say","note":"Dire is to say. Raconter is to narrate.","at":["cafe","terrasse"]},{"to":"fr_parler_verb","fr":"parler","hw":"parler","en":"to speak","note":"Parler is to speak. Raconter is to tell what happened, or a tale.","at":null,"lex":true,"examples":[{"who":"raconter","fr":"Raconte-moi ta journée.","en":"Tell me about your day."}]}]},"fr_ramener_verb":{"id":"fr_ramener_verb","lex":true,"fr":"ramener","en":"to bring back","ipa":"/ʁa.m(ə).ne/","say":"rah-muh-NAY","cefr":"A2","ex":["Je te ramène chez toi ?","Should I take you home?"],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_rapporter_verb","fr":"rapporter","hw":"rapporter","en":"to bring back; to report","note":"Rapporter brings an object back, or reports what happened. Ramener brings a person back, and it can bring an animal or an object back too.","at":null,"lex":true}]},"fr_rappeler_verb":{"id":"fr_rappeler_verb","lex":true,"fr":"rappeler","en":"to call back; to remind","ipa":"/ʁa.ple/","say":"rah-puh-LAY","cefr":"A1","ex":["Je te rappelle ce soir.","I'll call you back tonight."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_souvenir_verb","fr":"souvenir","hw":"souvenir","en":"to remember (se souvenir de)","note":"Se souvenir de is to remember. Se rappeler also means to remember, but the TLFi gives it a direct object (se rappeler son enfance), not de. Rappeler without se is to call back.","at":null,"lex":true,"examples":[{"who":"souvenir","fr":"Je me souviens de toi.","en":"I remember you."},{"who":"rappeler","fr":"Je me rappelle son nom.","en":"I remember his name."}]}]},"fr_rapporter_verb":{"id":"fr_rapporter_verb","lex":true,"fr":"rapporter","en":"to bring back; to report","ipa":"/ʁa.pɔʁ.te/","say":"rah-por-TAY","cefr":"A2","ex":["Rapporte-moi du pain, s'il te plaît.","Bring me back some bread, please."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_ramener_verb","fr":"ramener","hw":"ramener","en":"to bring back","note":"Ramener brings someone back to where they were. Rapporter brings an object back, or tells what you saw. Ramener can also bring an object back.","at":null,"lex":true}]},"fr_reconcilier_verb":{"id":"fr_reconcilier_verb","lex":true,"fr":"réconcilier","en":"to reconcile; to reconcile, to match up","ipa":"/ʁe.kɔ̃.si.lje/","say":"ray-kohn-see-LYAY","cefr":"B2","ex":["Elle a réconcilié ses deux amis.","She reconciled her two friends."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_concilier_verb","fr":"concilier","hw":"concilier","en":"to reconcile; to conciliate","note":"Concilier brings disagreeing people or contrary things into agreement. Réconcilier restores peace after a quarrel, and it can also align contrary things.","at":null,"lex":true}]},"fr_reflechir_verb":{"id":"fr_reflechir_verb","lex":true,"fr":"réfléchir","en":"to reflect; to ponder, to reflect","ipa":"/ʁe.fle.ʃiʁ/","say":"ray-flay-SHEER","cefr":"A1","ex":["Je dois réfléchir avant de répondre.","I need to think before I answer."],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_refleter_verb","fr":"refléter","hw":"refléter","en":"to reflect","note":"Refléter throws back light or an image. Réfléchir can do that too, and it is the verb for thinking something over.","at":["st_reflets","miroirs"]}]},"fr_reflet_noun":{"id":"fr_reflet_noun","lex":true,"fr":"reflet","en":"reflection","ipa":"/ʁə.flɛ/","say":"ruh-FLEH","cefr":"B1","ex":["Je vois mon reflet dans l'eau.","I can see my reflection in the water."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_reflexion_noun","fr":"réflexion","hw":"la réflexion","en":"reflection; thought, thinking","note":"Réflexion is thought, or thinking something over. Reflet is a reflection you see, as in a mirror.","at":["humanites","logique"]}]},"fr_regaler_verb":{"id":"fr_regaler_verb","lex":true,"fr":"régaler","en":"to treat (someone to a meal); 'se régaler': to enjoy a feast","ipa":"/ʁe.ɡa.le/","say":"ray-gah-LAY","cefr":"B2","ex":["Merci pour ce repas, on s'est régalés !","Thank you for the meal, we really enjoyed it!"],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_traiter_verb","fr":"traiter","hw":"traiter","en":"to treat","note":"Traiter has many senses: deal with, treat, handle. Régaler is to stand someone a meal.","at":["st_souffle","soigneurs"]}]},"fr_regarder_verb":{"id":"fr_regarder_verb","lex":true,"fr":"regarder","en":"to look at, watch","ipa":"/ʁə.ɡaʁ.de/","say":"ruh-gahr-DAY","cefr":"A1","ex":["Je regarde la télé.","I'm watching TV."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_voir_verb","fr":"voir","hw":"voir","en":"to see","note":"Voir is to see. Regarder is to direct your eyes at something.","at":null,"lex":true,"examples":[{"who":"voir","fr":"Je vois la mer.","en":"I see the sea."},{"who":"regarder","fr":"Regarde ce tableau.","en":"Look at this painting."}]}]},"fr_rejoindre_verb":{"id":"fr_rejoindre_verb","lex":true,"fr":"rejoindre","en":"to join","ipa":"/ʁə.ʒwɛ̃dʁ/","say":"ruh-ZHWANDR","cefr":"A2","ex":["Je te rejoins au café.","I'll meet you at the café."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_joindre_verb","fr":"joindre","hw":"joindre","en":"to join; to reach","note":"Joindre puts things together. Rejoindre goes and finds someone again, or gets back to a place.","at":["st_liens","st_liens"]}]},"fr_remplir_verb":{"id":"fr_remplir_verb","lex":true,"fr":"remplir","en":"to fill (up)","ipa":"/ʁɑ̃.pliʁ/","say":"rahn-PLEER","cefr":"A2","ex":["Peux-tu remplir la carafe d'eau, s'il te plaît ?","Can you fill the pitcher with water, please?"],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_emplir_verb","fr":"emplir","hw":"emplir","en":"to fill","note":"Emplir is a more literary word for to fill. Remplir is the ordinary word.","at":null,"lex":true}]},"fr_remporter_verb":{"id":"fr_remporter_verb","lex":true,"fr":"remporter","en":"to win","ipa":"/ʁɑ̃.pɔʁ.te/","say":"rahn-por-TAY","cefr":"B1","ex":["Notre équipe a remporté le match.","Our team won the match."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_gagner_verb","fr":"gagner","hw":"gagner","en":"to win; to earn","note":"Gagner is to win or to earn. Remporter is to carry off a victory or a prize.","at":null,"lex":true}]},"fr_renseigner_verb":{"id":"fr_renseigner_verb","lex":true,"fr":"renseigner","en":"to inform","ipa":"/ʁɑ̃.sɛ.ɲe/","say":"rahn-say-NYAY","cefr":"A2","ex":["Je me renseigne sur les horaires du train.","I'm finding out about the train times."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_informer_verb","fr":"informer","hw":"informer","en":"to inform","note":"Informer is to inform. Renseigner is to answer someone's question with the facts.","at":null,"lex":true}]},"fr_restaurer_verb":{"id":"fr_restaurer_verb","lex":true,"fr":"restaurer","en":"to restore; to dine, to eat","ipa":"/ʁɛs.tɔ.ʁe/","say":"rehs-toh-RAY","cefr":"B1","ex":["Ils restaurent une vieille maison.","They are restoring an old house."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_retablir_verb","fr":"rétablir","hw":"rétablir","en":"to restore; to reestablish","note":"Rétablir puts a situation or a person's health back. Restaurer repairs an object, and se restaurer means to eat.","at":null,"lex":true}]},"fr_retablir_verb":{"id":"fr_retablir_verb","lex":true,"fr":"rétablir","en":"to restore; to reestablish","ipa":"/ʁe.ta.bliʁ/","say":"ray-tah-BLEER","cefr":"B2","ex":["Le courant a été rétabli.","The power has been restored."],"noMnemonic":true,"verb":true,"group":"-ir","beret":"green","compares":[{"to":"fr_restaurer_verb","fr":"restaurer","hw":"restaurer","en":"to restore; to dine, to eat","note":"Restaurer is to repair a building or a work of art. Se restaurer is to take food and get your strength back. Rétablir is to put a situation, a right, or someone's health back as it was.","at":null,"lex":true}]},"fr_rigoler_verb":{"id":"fr_rigoler_verb","lex":true,"fr":"rigoler","en":"to laugh","ipa":"/ʁi.ɡɔ.le/","say":"ree-goh-LAY","cefr":"B1","ex":["On a bien rigolé hier soir.","We had a good laugh last night."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_rire_verb","fr":"rire","hw":"rire","en":"to laugh","note":"Rire is the ordinary word. Rigoler is informal.","at":["theatre","salle"]}]},"fr_rigolo_adj":{"id":"fr_rigolo_adj","lex":true,"fr":"rigolo","en":"funny","ipa":"/ʁi.ɡɔ.lo/","say":"ree-goh-LOH","cefr":"C1","ex":["Ton chapeau est rigolo !","Your hat is funny!"],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_drole_adj","fr":"drôle","hw":"drôle","en":"funny","note":"Drôle is the ordinary word. Rigolo is informal.","at":["theatre","salle"]}]},"fr_rompre_verb":{"id":"fr_rompre_verb","lex":true,"fr":"rompre","en":"to break","ipa":"/ʁɔ̃pʁ/","say":"ROHNPR","cefr":"A2","ex":["Le bateau a rompu ses amarres.","The boat broke its moorings."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_briser_verb","fr":"briser","hw":"briser","en":"to break","note":"Briser is to shatter. Rompre is to break off.","at":null,"lex":true},{"to":"fr_casser_verb","fr":"casser","hw":"casser","en":"to break","note":"Casser is the everyday word for to break. Rompre is often to break off a bond.","at":["st_porteurs","st_porteurs"]}]},"fr_sauter_verb":{"id":"fr_sauter_verb","lex":true,"fr":"sauter","en":"to jump","ipa":"/so.te/","say":"soh-TAY","cefr":"A2","ex":["Le chat saute sur la table.","The cat jumps onto the table."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_sursauter_verb","fr":"sursauter","hw":"sursauter","en":"to jump (with surprise)","note":"Sursauter is to jump because something startles you. Sauter is to jump.","at":["st_navigateurs","navigateurs"]}]},"fr_savoir_verb":{"id":"fr_savoir_verb","lex":true,"fr":"savoir","en":"to know (facts, how to)","ipa":"/sa.vwaʁ/","say":"sah-VWAHR","cefr":"A1","ex":["Je sais nager.","I can swim."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_connaitre_verb","fr":"connaître","hw":"connaître","en":"to know (be familiar with)","note":"Connaître is to be familiar with a person, a place, or a thing. Savoir is to know a fact, or how to do something.","at":null,"lex":true,"examples":[{"who":"savoir","fr":"Je sais nager.","en":"I know how to swim."},{"who":"connaître","fr":"Je connais Marie.","en":"I know Marie."}]}]},"fr_soiree_noun":{"id":"fr_soiree_noun","lex":true,"fr":"soirée","en":"evening (the whole of it); evening party","ipa":"/swa.ʁe/","say":"swah-RAY","cefr":"A1","ex":["Nous avons passé une bonne soirée.","We had a nice evening."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_soir_noun","fr":"soir","hw":"le soir","en":"evening","note":"Soir is the evening as a time of day. Soirée is the whole evening, or a party.","at":["horloge","place"],"examples":[{"who":"le soir","fr":"Ce soir, je sors.","en":"Tonight I'm going out."},{"who":"la soirée","fr":"Nous avons passé la soirée ensemble.","en":"We spent the evening together."}]}]},"fr_songer_verb":{"id":"fr_songer_verb","lex":true,"fr":"songer","en":"to think, dream","ipa":"/sɔ̃.ʒe/","say":"sohn-ZHAY","cefr":"A2","ex":["Il songe à partir en voyage.","He's thinking of going on a trip."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_penser_verb","fr":"penser","hw":"penser","en":"to think","note":"Penser is the ordinary word. Songer is to be thinking of something, in a more literary tone.","at":null,"lex":true}]},"fr_souci_noun":{"id":"fr_souci_noun","lex":true,"fr":"souci","en":"worry","ipa":"/su.si/","say":"soo-SEE","cefr":"B1","ex":["Ne te fais pas de souci.","Don't worry."],"noMnemonic":true,"g":"m","art":"le","ind":"un","compares":[{"to":"fr_inquietude_noun","fr":"inquiétude","hw":"l'inquiétude","en":"worry","note":"Inquiétude is an uneasy feeling. Souci is a worry, a problem on your mind.","at":null,"lex":true}]},"fr_soucieux_adj":{"id":"fr_soucieux_adj","lex":true,"fr":"soucieux","en":"worried; nervous, hesitant","ipa":"/su.sjø/","say":"soo-SYEUH","cefr":"B2","ex":["Il a l'air soucieux aujourd'hui.","He looks worried today."],"noMnemonic":true,"adj":true,"invariable":true,"compares":[{"to":"fr_inquiet_adj","fr":"inquiet","hw":"inquiet","en":"worried","note":"Inquiet is anxious. Soucieux is preoccupied, or mindful of something.","at":null,"lex":true}]},"fr_souvenir_verb":{"id":"fr_souvenir_verb","lex":true,"fr":"souvenir","en":"to remember (se souvenir de)","ipa":"/su.v(ə).niʁ/","say":"soo-vuh-NEER","cefr":"A1","ex":["Je me souviens de mes vacances.","I remember my vacation."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_rappeler_verb","fr":"rappeler","hw":"rappeler","en":"to call back; to remind","note":"Se rappeler, with a direct object, is to remember (se rappeler son enfance). Rappeler someone is to call them again. Se souvenir de is to remember, and it takes de.","at":null,"lex":true,"examples":[{"who":"souvenir","fr":"Je me souviens de toi.","en":"I remember you."},{"who":"rappeler","fr":"Je me rappelle son nom.","en":"I remember his name."}]}]},"fr_star_noun":{"id":"fr_star_noun","lex":true,"fr":"star","en":"star","ipa":"/staʁ/","say":"STAHR","cefr":"B1","ex":["Cette actrice est une vraie star.","This actress is a real star."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_etoile_noun","fr":"étoile","hw":"l'étoile","en":"star","note":"Étoile is a star in the sky. Star is a celebrity.","at":["ciel","etoiles"]},{"to":"fr_vedette_noun","fr":"vedette","hw":"la vedette","en":"star; flagship","note":"Vedette is the French word for a star performer. Star is the English loan.","at":null,"lex":true}]},"fr_surprendre_verb":{"id":"fr_surprendre_verb","lex":true,"fr":"surprendre","en":"to surprise; to catch out","ipa":"/syʁ.pʁɑ̃dʁ/","say":"sewr-PRAHNDR","cefr":"A1","ex":["Sa réponse m'a surpris.","His answer surprised me."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_etonner_verb","fr":"étonner","hw":"étonner","en":"to surprise","note":"Étonner is to astonish, to seem unexpected. Surprendre is to surprise someone, or to catch them at it.","at":null,"lex":true}]},"fr_tenter_verb":{"id":"fr_tenter_verb","lex":true,"fr":"tenter","en":"to try; to tempt","ipa":"/tɑ̃.te/","say":"tahn-TAY","cefr":"A2","ex":["Je vais tenter ma chance.","I'm going to try my luck."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_essayer_verb","fr":"essayer","hw":"essayer","en":"to try","note":"Essayer is to try, or to try on. Tenter is to attempt, or to tempt someone.","at":null,"lex":true}]},"fr_tomber_verb":{"id":"fr_tomber_verb","lex":true,"fr":"tomber","en":"to fall","ipa":"/tɔ̃.be/","say":"tohn-BAY","cefr":"A1","ex":["Attention, tu vas tomber !","Careful, you're going to fall!"],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_chuter_verb","fr":"chuter","hw":"chuter","en":"to fall","note":"Chuter is to fall, often a sharp drop, and it is used for prices or scores. Tomber is the everyday word.","at":["st_flaneurs","st_flaneurs"]}]},"fr_tracer_verb":{"id":"fr_tracer_verb","lex":true,"fr":"tracer","en":"to draw","ipa":"/tʁa.se/","say":"trah-SAY","cefr":"B1","ex":["Trace une ligne droite.","Draw a straight line."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_dessiner_verb","fr":"dessiner","hw":"dessiner","en":"to draw","note":"Dessiner is to draw. Tracer is to lay down a line or a route.","at":null,"lex":true}]},"fr_travailler_verb":{"id":"fr_travailler_verb","lex":true,"fr":"travailler","en":"to work","ipa":"/tʁa.va.je/","say":"trah-vah-YAY","cefr":"A1","ex":["Ma mère travaille à l'hôpital.","My mother works at the hospital."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_bosser_verb","fr":"bosser","hw":"bosser","en":"to work (informal)","note":"Bosser is informal for to work. Travailler is the ordinary word.","at":null,"lex":true}]},"fr_traverser_verb":{"id":"fr_traverser_verb","lex":true,"fr":"traverser","en":"to cross","ipa":"/tʁa.vɛʁ.se/","say":"trah-vehr-SAY","cefr":"A1","ex":["Nous traversons la rue.","We cross the street."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_croiser_verb","fr":"croiser","hw":"croiser","en":"to cross","note":"Croiser lays things across each other, or passes someone. Traverser goes across a space.","at":null,"lex":true}]},"fr_trompe_noun":{"id":"fr_trompe_noun","lex":true,"fr":"trompe","en":"trumpet; trunk of an elephant","ipa":"/tʁɔ̃p/","say":"TROHNP","cefr":"C1","ex":["L'éléphant boit avec sa trompe.","The elephant drinks with its trunk."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_trompette_noun_f","fr":"trompette","hw":"la trompette","en":"trumpet","note":"Trompette is the brass trumpet. Trompe is a hunting horn or a simple signaling horn, and it is also an elephant's trunk.","at":["conservatoire","orchestre"]}]},"fr_usager_noun":{"id":"fr_usager_noun","lex":true,"fr":"usager","en":"user","ipa":"/y.za.ʒe/","say":"ew-zah-ZHAY","cefr":"C2","ex":["Les usagers du métro attendent sur le quai.","Metro users wait on the platform."],"noMnemonic":true,"g":"m","art":"l'","ind":"un","compares":[{"to":"fr_utilisateur_noun","fr":"utilisateur","hw":"l'utilisateur","en":"user","note":"Utilisateur is a person who uses a tool or a product. Usager is a person who uses a service, or who has a right of use.","at":null,"lex":true}]},"fr_utilisateur_noun":{"id":"fr_utilisateur_noun","lex":true,"fr":"utilisateur","en":"user","ipa":"/y.ti.li.za.tœʁ/","say":"ew-tee-lee-zah-TUHR","cefr":"C1","ex":["L'utilisateur crée un mot de passe.","The user creates a password."],"noMnemonic":true,"g":"m","art":"l'","ind":"un","compares":[{"to":"fr_usager_noun","fr":"usager","hw":"l'usager","en":"user","note":"Usager is someone using a service, or holding a right of use. Utilisateur is someone using a tool or a product.","at":null,"lex":true}]},"fr_vedette_noun":{"id":"fr_vedette_noun","lex":true,"fr":"vedette","en":"star; flagship","ipa":"/və.dɛt/","say":"vuh-DEHT","cefr":"B2","ex":["Cet acteur est une vedette.","This actor is a star."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_etoile_noun","fr":"étoile","hw":"l'étoile","en":"star","note":"Étoile is up in the sky. Vedette is a performer who is a star.","at":["ciel","etoiles"]},{"to":"fr_star_noun","fr":"star","hw":"la star","en":"star","note":"Star is the loanword. Vedette is the French word.","at":null,"lex":true}]},"fr_vers_prep":{"id":"fr_vers_prep","lex":true,"fr":"vers","en":"toward; around (a time)","ipa":"/vɛʁ/","say":"VEHR","cefr":"A1","ex":["Il marche vers la gare.","He walks toward the station."],"noMnemonic":true,"adv":true,"gramLine":"preposition · invariable","compares":[{"to":"fr_envers_prep","fr":"envers","hw":"envers","en":"toward (feelings or attitude)","note":"Envers is toward a person, about feelings or behavior. Vers is toward a place, or around a time.","at":null,"lex":true,"examples":[{"who":"vers","fr":"Je vais vers la gare.","en":"I'm heading toward the station."},{"who":"envers","fr":"Il est gentil envers elle.","en":"He is kind toward her."}]}]},"fr_vociferer_verb":{"id":"fr_vociferer_verb","lex":true,"fr":"vociférer","en":"to shout, scream, vociferate","ipa":"/vɔ.si.fe.ʁe/","say":"voh-see-fay-RAY","cefr":"C2","ex":["Le supporter vocifère contre l'arbitre.","The fan yells at the referee."],"noMnemonic":true,"verb":true,"group":"-er","beret":"red","compares":[{"to":"fr_crier_verb","fr":"crier","hw":"crier","en":"to shout","note":"Crier is to shout. Vociférer is to yell furiously.","at":["theatre","tournage"]}]},"fr_voir_verb":{"id":"fr_voir_verb","lex":true,"fr":"voir","en":"to see","ipa":"/vwaʁ/","say":"VWAHR","cefr":"A1","ex":["Je vois la mer de ma fenêtre.","I can see the sea from my window."],"noMnemonic":true,"verb":true,"group":"irregular","beret":"gold","compares":[{"to":"fr_regarder_verb","fr":"regarder","hw":"regarder","en":"to look at, watch","note":"Regarder is to look at something on purpose. Voir is to see what is in front of you, and the TLFi pairs it with regarder the way entendre pairs with écouter.","at":null,"lex":true,"examples":[{"who":"voir","fr":"Je vois la mer.","en":"I see the sea."},{"who":"regarder","fr":"Regarde ce tableau.","en":"Look at this painting."}]}]},"fr_volonte_noun":{"id":"fr_volonte_noun","lex":true,"fr":"volonté","en":"will","ipa":"/vɔ.lɔ̃.te/","say":"voh-lohn-TAY","cefr":"A2","ex":["Il a beaucoup de volonté.","He has a lot of willpower."],"noMnemonic":true,"g":"f","art":"la","ind":"une","compares":[{"to":"fr_gre_noun","fr":"gré","hw":"le gré","en":"will; liking","note":"Gré is will in set phrases such as à mon gré, as I see fit. Volonté is willpower, or what you want.","at":["humanites","ethique"]}]},"fr_votre_det":{"id":"fr_votre_det","lex":true,"fr":"votre","en":"your (polite or plural)","ipa":"/vɔtʁ/","say":"VOTR","cefr":"A1","ex":["Quel est votre nom ?","What is your name?"],"noMnemonic":true,"adv":true,"gramLine":"determiner","compares":[{"to":"fr_ton_det","fr":"ton","hw":"ton","en":"your (friendly, one person)","note":"Ton goes with tu. Votre goes with vous.","at":["ecole","theatre"]}]}};
